import HeroBanner from "../components/banner/HeroBanner";
import CategoryProductList from "../components/category/CategoryProductList";
import ProductList from "../components/product/ProductList";

function Home() {
  return (
    /* Đổi tên class bọc ngoài cùng thành modern-home-page */
    <div className="modern-home-page w-100 overflow-hidden">
      
      {/* 1. Banner */}
      <HeroBanner />

      {/* 2. Khối Danh Mục Sản Phẩm */}
      <section className="modern-section-category py-5 bg-light w-100">
        <div className="container">
          <div className="row justify-content-center text-center mb-4">
            <div className="col-12">
              <h2 className="fw-semibold text-dark mb-2">Khám Phá Theo Danh Mục</h2>
              <p className="text-muted small mb-0">Tìm kiếm nhanh những món đồ phù hợp cho không gian của bạn</p>
            </div>
          </div>
          {/* Component con danh mục */}
          <CategoryProductList />
        </div>
      </section>

      {/* 3. Khối Sản Phẩm Nổi Bật */}
      <section className="modern-section-products py-5 w-100">
        <div className="container">
          <div className="row justify-content-center text-center mb-5">
            <div className="col-12">
              <span className="text-uppercase tracking-wider small text-secondary d-block mb-1">Sản phẩm nổi bật</span>
              <h2 className="fw-bold text-dark">Nội Thất Thông Minh</h2>
              <div className="mx-auto bg-dark mt-2" style={{ width: "50px", height: "2px" }}></div>
            </div>
          </div>
          {/* Component con sản phẩm */}
          <ProductList />
        </div>
      </section>

    </div>
  );
}

export default Home;
